  /** Files for the turn (feature promptAttachments; types in `harnesses[].attachmentTypes`). Inline data is placed in a per-turn guest directory; images go to the harness natively and every attachment is named in the prompt by guest path. */
  attachments?: PromptAttachment[];
  options?: PromptOptions;
  /** Bounds the turn (default: the daemon's harness.defaultTurnTimeout, 1h unless configured; at most 86400); the guest kills the harness at `turnDeadlineAt` and the turn fails with `turn_timeout`. While it runs, the turn holds the VM's auto-stop (feature promptTurnLease). */
